// async fileFilter that delays validation
function asyncFilter(req, file, cb) {
  setTimeout(() => {
    // simulate async check
    if (file.mimetype !== 'image/png') return cb(null, false);
    cb(null, true);
  }, 1000);
}
// If the client aborts the upload within that second, Multer 2.0‑2.4 will crash.
